UPDATE user_membership_quota
SET quota_balance_minor = #{quotaBalanceMinor,jdbcType=BIGINT},
    quota_period_started_at =
        #{quotaPeriodStartedAt,jdbcType=TIMESTAMP_WITH_TIMEZONE},
    quota_period_ends_at =
        #{quotaPeriodEndsAt,jdbcType=TIMESTAMP_WITH_TIMEZONE}
WHERE id = #{id,jdbcType=BIGINT}
  AND login_identity_id = #{loginIdentityId,jdbcType=BIGINT}

UPDATE user_membership_quota
SET membership_tier = 0,
    membership_expires_at = NULL,
    quota_balance_minor = #{freeQuotaMinor,jdbcType=BIGINT},
    quota_period_started_at = #{now,jdbcType=TIMESTAMP_WITH_TIMEZONE},
    quota_period_ends_at = #{freeQuotaEndsAt,jdbcType=TIMESTAMP_WITH_TIMEZONE}
WHERE login_identity_id = #{loginIdentityId,jdbcType=BIGINT}
  AND membership_tier BETWEEN 1 AND 6
  AND (
      membership_expires_at IS NULL
      OR membership_expires_at <= #{now,jdbcType=TIMESTAMP_WITH_TIMEZONE}
  )

WITH raw_refund(login_identity_id, refund_minor) AS ( VALUES
( #{candidate.loginIdentityId,jdbcType=BIGINT}, #{candidate.reservedQuotaMinor,jdbcType=BIGINT} )
), refund AS ( SELECT login_identity_id, SUM(refund_minor) AS refund_minor FROM raw_refund GROUP BY login_identity_id ) UPDATE user_membership_quota quota SET quota_balance_minor = quota.quota_balance_minor + refund.refund_minor FROM refund WHERE quota.login_identity_id = refund.login_identity_id

